public final String readUtf(final int constantPoolEntryIndex,final char[] charBuffer) {
    int start = constantPoolTableOffset + // move to first index of table
               constantPoolTableSize * 8 + // move to offset of given entry
               constantPoolEntryIndex * ConstantPoolEntry.UTF8_SIZE + // move to offset of value
               ConstantPoolEntry.UTF8_LENGTH; // move to length of utf8 encoded string
    int length = charBuffer.length; // buffer size should be large enough for utf8 encoding
    int read; // number of bytes read
    int bytesLeftToRead = length; // number of bytes left to read
    // read utf8 counting 1 bytes for first byte and 2 bytes for every utf shift of next bytes
    do {
        read = classFileBuffer . read ( charBuffer , start - bytesLeftToRead , bytesLeftToRead );
        if (read < 0) {
            // end of file: stop reading
            break;
        }
        bytesLeftToRead -= read;
        // Adjust buffer size for next utf shift
        if ((read != 1) && (charBuffer[start - bytesLeftToRead] & 0xe0) == 0xc0) {
            length += read - 1;
        }
    } while (bytesLeftToRead > 0);
    return new String ( charBuffer , 0 , length );
}

