private void reload(List<Set<Integer>> bucketsByLabel, List<Integer> labels, int minLabel) {
    // Assumptions: All buckets are initially empty, and labels are non-negative integers
    // This method restructures the buckets such that vertices labeled 'minLabel' are moved to label 0,
    // and all vertices are updated to reflect the new labels.

    for (int i = 0; i < bucketsByLabel.size(); i++) {
        int label = bucketsByLabel.get(i).contains(minLabel) ? 0 : i;
        if (!bucketsByLabel.get(i).contains(label)) {
            if (!bucketsByLabel.get(i).isEmpty()) {
                bucketsByLabel.get(i).clear();
            }
            bucketsByLabel.get(i).add(label);
        }
    }
}

