private static int digitValue(final char c){
    // Check if the character is in the range of ASCII digits
    if ((c >= '0') && (c <= '9')) {
        return c - '0';
    } else if ((c >= 'a') && (c <= 'z')) {
        return c - 'a' + 10;
    } else if ((c >= 'A') && (c <= 'Z')) {
        return c - 'A' + 10;
    } else {
        // Return -1 if the character is not a valid base-36 digit
        return -1;
    }
}

