public static int computeUTF8Size(CharSequence str, int index, int len) {
    int UTF8_SIZE = 0;
    for (int i = index; i < index + len; i++) {
        int value = str.charAt(i);
        if ((value & 0xF8) == 0xF0) {
            UTF8_SIZE += 4; // Four bytes
        } else if ((value & 0xE0) == 0xE0) {
            UTF8_SIZE += 3; // Three bytes
        } else if ((value & 0xC0) == 0xC0) {
            UTF8_SIZE += 2; // Two bytes
        } else {
            UTF8_SIZE++; // One byte
        }
    }
    return UTF8_SIZE;
}

