public long readRawVarint64() throws IOException {
    int len = 0;
    while ((data[dataPosition + len >> 3] & (1 << (len & 7))) == 0) {
        len++;
    }
    long result = 0;
    for (int i = 0; i < len; i++) {
        result |= ((long)(data[dataPosition + len - 1 - i])) << (7 * i);
    }
    return result;
}

